//! Typed view of `schema/v23.json`, the canonical schema extracted from the legacy Qt/C++ tree.
//!
//! The JSON is generated by `tools/extract-schema.py` from `src/database/ObjectStoreTyped.cpp`
//! and embedded at compile time, so a build can never disagree with the checked-in schema.

use std::collections::BTreeMap;
use std::sync::OnceLock;

use serde::Deserialize;

/// The canonical schema document, as emitted by `tools/extract-schema.py`.
#[derive(Debug, Clone, Deserialize)]
pub struct Schema {
    pub schema_version: u32,
    pub generated_by: String,
    pub source_files: Vec<String>,
    pub dialects: Vec<String>,
    /// Base type (`"double"`, `"string"`, …) to that type's name in each dialect.
    pub native_types: BTreeMap<String, BTreeMap<String, String>>,
    pub primary_key_declaration: BTreeMap<String, String>,
    pub add_foreign_key: BTreeMap<String, String>,
    pub identifier_quote: BTreeMap<String, String>,
    pub tables: Vec<Table>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Table {
    pub name: String,
    /// The C++ class this table stores, e.g. `Hop` or `Folder<Hop>`.
    pub cpp_type: String,
    pub primary_key: PrimaryKey,
    /// Every column except the primary key and the foreign keys.
    ///
    /// Foreign keys are deliberately absent: the C++ omits them from `CREATE TABLE` and adds them
    /// afterwards with `ALTER TABLE`, so that table creation order does not matter.
    pub columns: Vec<Column>,
    pub foreign_keys: Vec<ForeignKey>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct PrimaryKey {
    pub name: String,
    pub property: Option<String>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Column {
    pub name: String,
    /// Key into [`Schema::native_types`].
    pub base_type: String,
    /// The `ObjectStore::FieldType` this came from: `Double`, `Enum`, `Money`, …
    ///
    /// Several of these share one base type — `Enum` and `Unit` are both stored as strings, and a
    /// `Money` field contributes a `string` currency column followed by an `int` amount column.
    pub field_type: String,
    pub property: Option<String>,
    /// For `Enum` and `Unit` columns, the C++ string mapping that encodes the value.
    pub string_mapping: Option<String>,
    /// Set when the column is inherited from a `*_COMMON_FIELDS` vector rather than declared on
    /// the table itself.
    pub from_common_set: Option<String>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct ForeignKey {
    pub column: String,
    pub references_table: String,
    pub references_column: String,
    pub property: Option<String>,
    pub from_common_set: Option<String>,
}

const SCHEMA_JSON: &str = include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/../../../schema/v23.json"));

/// The canonical schema, parsed once.
///
/// # Panics
///
/// If the embedded JSON does not match [`Schema`]. That is a build-time inconsistency between
/// `tools/extract-schema.py` and this crate, not a runtime condition worth propagating.
pub fn schema() -> &'static Schema {
    static SCHEMA: OnceLock<Schema> = OnceLock::new();
    SCHEMA.get_or_init(|| serde_json::from_str(SCHEMA_JSON).expect("schema/v23.json does not match bt_schema::Schema"))
}

impl Schema {
    pub fn table(&self, name: &str) -> Option<&Table> {
        self.tables.iter().find(|t| t.name == name)
    }
}
